function achievementArt(kind, id, size = 64, level = 1) {
    const key = kind === 'badge' && Object.prototype.hasOwnProperty.call(ACHIEVEMENT_BADGE_ART, id + ':1')
        ? id + ':' + Math.max(1, Math.min(3, Math.trunc(Number(level)) || 1)) : id;
    const rect = (kind === 'trophy' ? ACHIEVEMENT_TROPHY_ART : ACHIEVEMENT_BADGE_ART)[key];
    if (!rect) return '';
    const [atlasIndex, x, y, width, height] = rect;
    const atlas = ACHIEVEMENT_ATLASES[atlasIndex];
    const cutout = ACHIEVEMENT_CUTOUTS[kind + ':' + key] || 'none';
    const side = Math.max(width, height);
    const pct = n => Number(n.toFixed(6));
    const safeSize = Math.max(1, Math.min(512, Number(size) || 64));
    // The inner viewport clips the source rectangle; percentages keep it correct at every CSS size.
    return `<span class="jtfag-art" data-achievement-kind="${kind}" data-achievement-id="${key}" aria-hidden="true" style="width:${safeSize}px;height:${safeSize}px"><span class="jtfag-art-window" style="clip-path:${cutout};left:${pct((side-width)/side*50)}%;top:${pct((side-height)/side*50)}%;width:${pct(width/side*100)}%;height:${pct(height/side*100)}%"><img src="${atlas.file}" alt="" draggable="false" loading="lazy" decoding="async" width="${atlas.width}" height="${atlas.height}" style="left:${pct(-x/width*100)}%;top:${pct(-y/height*100)}%;width:${pct(atlas.width/width*100)}%;height:${pct(atlas.height/height*100)}%"></span></span>`;
}

